import json as _j, re as _re
def lookup(handles, fields="id,name,username,description,public_metrics,verified,created_at"):
    """Fetch Twitter profiles for handles (list or comma-separated string)."""
    if isinstance(handles, str):
        s = handles.strip()
        try:
            v = _j.loads(s)
            handles = v if isinstance(v, list) else [v]
        except Exception:
            handles = _re.split(r'[,\s]+', s.strip('[]'))
    handles = [h.strip().lstrip('@') for h in handles if str(h).strip().lstrip('@')]
    out = []
    for h in handles:
        r = tools.fetch("https://api.twitter.com/2/users/by/username/" + h,
                        params={"user.fields": fields})
        try:
            d = r.get("data") if isinstance(r, dict) else None
        except Exception:
            d = None
        if d:
            pm = d.get("public_metrics", {})
            out.append({"h": h, "id": d.get("id"), "name": d.get("name"),
                        "ver": d.get("verified"), "fol": pm.get("followers_count"),
                        "bio": (d.get("description") or "")[:160]})
        else:
            out.append({"h": h, "err": r})
    return out

